namespace fuse::renderer::rt_effects {

namespace {
constexpr u32 kFrameStride = 768u; ///< ring slot size (>= sizeof(RtfxFrameConstants), 256-aligned)
static_assert(sizeof(RtfxFrameConstants) <= kFrameStride, "frame ring slot");
/// G-buffer attachments the kernels read (GBufferAttachment order): RT0 normal + AO, RT2 roughness, RT4 depth.
constexpr u32 kGBufferAttachments[3] = {0u, 2u, 4u};

[[maybe_unused]] u32 groups(u32 items, u32 size) { return items == 0u ? 1u : (items + size - 1u) / size; }

/// Gauss-Jordan inverse in double (column-major).
bool invert(const f32 in[16], f64 out[16]) {
    f64 a[4][8];
    for (u32 r = 0; r < 4; ++r) {
        for (u32 c = 0; c < 4; ++c) {
            a[r][c] = in[c * 4 + r];
            a[r][c + 4] = r == c ? 1.0 : 0.0;
        }
    }
    for (u32 c = 0; c < 4; ++c) {
        u32 piv = c;
        for (u32 r = c + 1; r < 4; ++r) {
            if (std::fabs(a[r][c]) > std::fabs(a[piv][c])) {
                piv = r;
            }
        }
        if (std::fabs(a[piv][c]) < 1e-30) {
            return false;
        }
        for (u32 k = 0; k < 8; ++k) {
            std::swap(a[c][k], a[piv][k]);
        }
        const f64 d = a[c][c];
        for (u32 k = 0; k < 8; ++k) {
            a[c][k] /= d;
        }
        for (u32 r = 0; r < 4; ++r) {
            if (r != c) {
                const f64 f = a[r][c];
                for (u32 k = 0; k < 8; ++k) {
                    a[r][k] -= f * a[c][k];
                }
            }
        }
    }
    for (u32 r = 0; r < 4; ++r) {
        for (u32 c = 0; c < 4; ++c) {
            out[c * 4 + r] = a[r][c + 4];
        }
    }
    return true;
}

void store3(f32 dst[3], const math::Vec3& v) {
    dst[0] = v.x;
    dst[1] = v.y;
    dst[2] = v.z;
}

/// Unit vector of a light's `direction` (fallback when degenerate), in f32.
math::Vec3 unitDirection(const f32 d[3], const math::Vec3& fallback) {
    const math::Vec3 v{d[0], d[1], d[2]};
    const f32 l = std::sqrt(v.x * v.x + v.y * v.y + v.z * v.z);
    if (!(l > 1e-20f)) {
        return fallback;
    }
    return {v.x / l, v.y / l, v.z / l};
}

#if defined(FUSE_VULKAN_BACKEND)
struct Code {
    const u32* words = nullptr;
    usize bytes = 0;
};
template <usize N>
Code code(const u32 (&spv)[N]) {
    return Code{spv, sizeof(spv)};
}
#endif
} // namespace

bool packShadowLight(u32 slot, const gpu_scene::GpuLight& light, u32 samples, RtfxShadowLight& out) {
    out = RtfxShadowLight{};
    out.slot = slot;
    out.samples = 1u;
    const math::Vec3 up{0.f, 1.f, 0.f};
    switch (light.type) {
    case static_cast<u32>(gpu_scene::GpuLightType::Directional): {
        const math::Vec3 travel = unitDirection(light.direction, math::Vec3{0.f, -1.f, 0.f});
        store3(out.direction, math::Vec3{-travel.x, -travel.y, -travel.z});
        if (light.cosOuter < ltc::kMinSunCos) {
            out.kind = kRtfxLightSun;
            out.cosCone = std::clamp(light.cosOuter, -1.f, 1.f);
            out.samples = std::clamp(samples, 1u, kRtfxMaxSamples);
        } else {
            out.kind = kRtfxLightDirectional;
        }
        return true;
    }
    case static_cast<u32>(gpu_scene::GpuLightType::Point):
    case static_cast<u32>(gpu_scene::GpuLightType::Spot):
        out.kind = kRtfxLightPoint;
        std::memcpy(out.position, light.position, sizeof(out.position));
        store3(out.direction, unitDirection(light.direction, up));
        return true;
    case kRtfxLightRect:
    case kRtfxLightDisk: {
        // ltc::makeRectLight / makeDiskLight encoding: direction = lit-side normal, flags = tangent
        // (octahedral snorm16x2), cosInner / cosOuter = half extents.
        const math::Vec3 normal = ltc::safe_unit(math::Vec3{light.direction[0], light.direction[1], light.direction[2]},
                                                 math::Vec3{0.f, 0.f, -1.f});
        math::Vec3 ex{};
        math::Vec3 ey{};
        ltc::area_axes(normal, ltc::decode_tangent(light.flags), light.cosInner, light.cosOuter, ex, ey);
        out.kind = light.type == kRtfxLightRect ? kRtfxLightRect : kRtfxLightDisk;
        std::memcpy(out.position, light.position, sizeof(out.position));
        store3(out.axisX, ex);
        store3(out.axisY, ey);
        store3(out.direction, normal);
        out.samples = std::clamp(samples, 1u, kRtfxMaxSamples);
        return true;
    }
    default:
        out.slot = 0xFFFFFFFFu;
        return false;
    }
}

bool packHitLight(u32 slot, const gpu_scene::GpuLight& light, bool shadowed, RtfxHitLight& out) {
    out = RtfxHitLight{};
    if (light.type != static_cast<u32>(gpu_scene::GpuLightType::Directional)) {
        return false;
    }
    const math::Vec3 travel = unitDirection(light.direction, math::Vec3{0.f, -1.f, 0.f});
    store3(out.direction, math::Vec3{-travel.x, -travel.y, -travel.z});
    out.shadowed = shadowed ? 1u : 0u;
    for (u32 c = 0; c < 3u; ++c) {
        out.irradiance[c] = light.color[c] * light.intensity;
    }
    out.slot = slot;
    return true;
}

bool buildFrameConstants(const RtEffectsFrameDesc& desc, u32 width, u32 height, RtfxFrameConstants& c) {
    c = RtfxFrameConstants{};
    f64 inv[16];
    if (width == 0u || height == 0u || !invert(desc.viewProj, inv)) {
        return false;
    }
    for (u32 i = 0; i < 16u; ++i) {
        c.invViewProj[i] = static_cast<f32>(inv[i]);
    }
    c.view.width = width;
    c.view.height = height;
    u32 count = 0;
    for (u32 i = 0; i < std::min(desc.shadowLightCount, kRtfxMaxShadowLights); ++i) {
        const RtShadowLightDesc& l = desc.shadowLights[i];
        if (packShadowLight(l.slot, l.light, l.samples, c.shadowLights[count])) {
            c.view.slots[count] = l.slot;
            ++count;
        }
    }
    c.view.count = count;
    u32 hits = 0;
    for (u32 i = 0; i < std::min(desc.hitLightCount, kRtfxMaxHitLights); ++i) {
        const RtHitLightDesc& l = desc.hitLights[i];
        hits += packHitLight(l.slot, l.light, l.shadowed, c.hitLights[hits]) ? 1u : 0u;
    }
    c.hitLightCount = hits;
    c.tlas = desc.tlasAddress;
    std::memcpy(c.cameraPosition, desc.cameraPosition, sizeof(c.cameraPosition));
    c.frameIndex = desc.frameIndex;
    c.invWidth = 1.f / static_cast<f32>(width);
    c.invHeight = 1.f / static_cast<f32>(height);
    c.scene = desc.scene;
    c.flags = desc.hitShadows ? kRtfxFlagHitShadows : 0u;
    c.reflectionSamples = std::min(desc.reflectionSamples, kRtfxMaxSamples);
    c.normalBias = desc.normalBias;
    c.viewBias = desc.viewBias;
    c.farDistance = desc.farDistance;
    c.mirrorRoughness = desc.mirrorRoughness;
    std::memcpy(c.ambient, desc.ambient, sizeof(c.ambient));
    std::memcpy(c.sky, desc.sky, sizeof(c.sky));
    c.shadowCullMask = desc.shadowCullMask & rt::kRtMaskAll;
    c.reflectionCullMask = desc.reflectionCullMask & rt::kRtMaskAll;
    c.seed = desc.seed;
    return true;
}

// --- RtEffects --------------------------------------------------------------------------------------------
RtEffects::~RtEffects() { destroy(); }

bool RtEffects::init(const RtEffectsDesc& desc) {
    destroy();
    m_desc = desc;
#if defined(FUSE_VULKAN_BACKEND)
    if (desc.allocator == nullptr || desc.bindless == nullptr || desc.framesInFlight == 0u) {
        m_reason = "allocator / bindless / framesInFlight missing";
        return false;
    }
    const rt::RtCapabilities caps = rt::queryRtCapabilities(desc.device);
    if (!caps.usable) {
        m_reason = caps.reason;
        return false;
    }
    m_initialized = true; // destroy() releases partial state from here on
    BufferDesc ring{};
    ring.size = static_cast<usize>(desc.framesInFlight) * kFrameStride;
    ring.usage = static_cast<BufferUsage>(static_cast<u32>(BufferUsage::Storage) | static_cast<u32>(BufferUsage::ShaderDeviceAddress));
    ring.memoryUsage = MemoryUsage::CpuToGpu;
    ring.name = "rt_effects.frame";
    if (!m_desc.allocator->createBuffer(ring, m_frameRing) || m_frameRing.mapped == nullptr || m_frameRing.deviceAddress == 0u) {
        destroy();
        m_reason = "frame ring allocation failed";
        return false;
    }
    if (!createPipelines(desc.language)) {
        destroy();
        m_reason = "rt_effects kernels not built for the requested language / pipeline creation failed";
        return false;
    }
    if (desc.width > 0u && desc.height > 0u && !createOutput(desc.width, desc.height)) {
        destroy();
        m_reason = "output allocation failed";
        return false;
    }
    m_reason = "ok";
    return true;
#else
    m_reason = "stub backend";
    return false;
#endif
}

void RtEffects::destroy() {
    if (!m_initialized) {
        return;
    }
#if defined(FUSE_VULKAN_BACKEND)
    collectRetired(~0ull);
    for (BindlessSlotHandle& slot : m_gbufferSlots) {
        if (slot.isValid()) {
            m_desc.bindless->unregisterSlot(slot);
        }
    }
    if (m_output.handle != nullptr) {
        m_desc.allocator->destroyBuffer(m_output);
    }
    if (m_frameRing.handle != nullptr) {
        m_desc.allocator->destroyBuffer(m_frameRing);
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    for (void*& pipeline : m_pipelines) {
        if (pipeline != nullptr) {
            vkDestroyPipeline(device, static_cast<VkPipeline>(pipeline), nullptr);
            pipeline = nullptr;
        }
    }
    if (m_layoutHandle != nullptr) {
        vkDestroyPipelineLayout(device, static_cast<VkPipelineLayout>(m_layoutHandle), nullptr);
    }
#endif
    m_layoutHandle = nullptr;
    m_output = Buffer{};
    m_outputQueue = rg::kNoQueue;
    m_frameRing = Buffer{};
    m_frameAddress = 0;
    m_gbuffer = nullptr;
    for (u32 i = 0; i < kGBufferInputs; ++i) {
        m_gbufferImages[i] = nullptr;
        m_gbufferSlots[i] = BindlessSlotHandle{};
        m_gbufferHandles[i] = 0u;
    }
    for (Retired& r : m_retired) {
        r = Retired{};
    }
    m_width = m_height = 0;
    m_layout = RtEffectsOutputLayout{};
    m_recordCount = 0;
    m_language = "none";
    m_stats = RtEffectsStats{};
    m_initialized = false;
}

bool RtEffects::createPipelines(RtEffectsKernelLanguage language) {
#if defined(FUSE_VULKAN_BACKEND)
    Code k[kKernelCount]{};
    bool found = false;
#if defined(FUSE_RT_EFFECTS_SLANG)
    if (language == RtEffectsKernelLanguage::Auto || language == RtEffectsKernelLanguage::Slang) {
        k[kShadows] = code(kRtfxShadowsSlangSpv);
        k[kReflections] = code(kRtfxReflectionsSlangSpv);
        m_language = "slang";
        found = true;
    }
#endif
#if defined(FUSE_RT_EFFECTS_GLSL)
    if (!found && (language == RtEffectsKernelLanguage::Auto || language == RtEffectsKernelLanguage::Glsl)) {
        k[kShadows] = code(kRtfxShadowsGlslSpv);
        k[kReflections] = code(kRtfxReflectionsGlslSpv);
        m_language = "glsl";
        found = true;
    }
#endif
    (void)language;
    if (!found) {
        return false;
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    VkDescriptorSetLayout setLayout = static_cast<VkDescriptorSetLayout>(m_desc.bindless->layoutHandle());
    VkPushConstantRange range{VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(RtfxPush)};
    VkPipelineLayoutCreateInfo layoutInfo{};
    layoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
    layoutInfo.setLayoutCount = setLayout != VK_NULL_HANDLE ? 1u : 0u;
    layoutInfo.pSetLayouts = &setLayout;
    layoutInfo.pushConstantRangeCount = 1;
    layoutInfo.pPushConstantRanges = &range;
    VkPipelineLayout layout = VK_NULL_HANDLE;
    if (vkCreatePipelineLayout(device, &layoutInfo, nullptr, &layout) != VK_SUCCESS) {
        return false;
    }
    m_layoutHandle = layout;
    const VkPipelineCreateFlags createFlags = static_cast<VkPipelineCreateFlags>(m_desc.bindless->pipelineCreateFlags());
    for (u32 i = 0; i < kKernelCount; ++i) {
        VkShaderModuleCreateInfo moduleInfo{};
        moduleInfo.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
        moduleInfo.codeSize = k[i].bytes;
        moduleInfo.pCode = k[i].words;
        VkShaderModule module = VK_NULL_HANDLE;
        if (vkCreateShaderModule(device, &moduleInfo, nullptr, &module) != VK_SUCCESS) {
            return false;
        }
        VkComputePipelineCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
        info.flags = createFlags;
        info.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
        info.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
        info.stage.module = module;
        info.stage.pName = "main";
        info.layout = layout;
        VkPipeline pipeline = VK_NULL_HANDLE;
        const VkResult result = vkCreateComputePipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
        vkDestroyShaderModule(device, module, nullptr);
        m_pipelines[i] = pipeline;
        if (result != VK_SUCCESS) {
            return false;
        }
    }
    return true;
#else
    (void)language;
    return false;
#endif
}

bool RtEffects::createOutput(u32 width, u32 height) {
    const RtEffectsOutputLayout layout = RtEffectsOutputLayout::compute(width, height);
    BufferDesc d{};
    d.size = static_cast<usize>(layout.bytes);
    d.usage = static_cast<BufferUsage>(static_cast<u32>(BufferUsage::Storage) | static_cast<u32>(BufferUsage::ShaderDeviceAddress) |
                                       static_cast<u32>(BufferUsage::TransferSrc));
    d.memoryUsage = MemoryUsage::GpuOnly;
    d.name = "rt_effects.output";
    Buffer fresh{};
    if (!m_desc.allocator->createBuffer(d, fresh) || fresh.deviceAddress == 0u) {
        if (fresh.handle != nullptr) {
            m_desc.allocator->destroyBuffer(fresh);
        }
        return false;
    }
    if (m_output.handle != nullptr) {
        Retired old{};
        old.buffer = m_output;
        if (!retire(old)) {
            m_desc.allocator->destroyBuffer(fresh);
            return false;
        }
    }
    m_output = fresh;
    m_outputQueue = rg::kNoQueue;
    m_layout = layout;
    m_width = width;
    m_height = height;
    ++m_stats.outputRebuilds;
    return true;
}

bool RtEffects::retire(const Retired& r) {
    for (Retired& slot : m_retired) {
        if (!slot.used) {
            slot = r;
            slot.serial = m_frameSerial;
            slot.used = true;
            return true;
        }
    }
    return false;
}

u32 RtEffects::collectRetired(u64 completedSerial) {
    u32 collected = 0;
    for (Retired& r : m_retired) {
        if (!r.used || r.serial > completedSerial) {
            continue;
        }
        for (BindlessSlotHandle& slot : r.slots) {
            if (slot.isValid()) {
                m_desc.bindless->unregisterSlot(slot);
            }
        }
        if (r.buffer.handle != nullptr) {
            m_desc.allocator->destroyBuffer(r.buffer);
        }
        r = Retired{};
        ++collected;
    }
    return collected;
}

bool RtEffects::bindGBuffer(const material_resolve::MaterialResolve& gbuffer) {
    bool changed = m_gbuffer != &gbuffer;
    for (u32 i = 0; i < kGBufferInputs && !changed; ++i) {
        changed = gbuffer.gbufferImage(kGBufferAttachments[i]).image != m_gbufferImages[i];
    }
    if (!changed) {
        return true;
    }
    Retired old{};
    bool any = false;
    for (u32 i = 0; i < kGBufferInputs; ++i) {
        old.slots[i] = m_gbufferSlots[i];
        any = any || m_gbufferSlots[i].isValid();
        m_gbufferSlots[i] = BindlessSlotHandle{};
        m_gbufferImages[i] = nullptr;
        m_gbufferHandles[i] = 0u;
    }
    if (any && !retire(old)) {
        return false;
    }
    m_gbuffer = &gbuffer;
    for (u32 i = 0; i < kGBufferInputs; ++i) {
        const Texture& image = gbuffer.gbufferImage(kGBufferAttachments[i]);
        if (image.image == nullptr) {
            return false;
        }
        m_gbufferSlots[i] = m_desc.bindless->registerTextureSlot(image, false);
        if (!m_gbufferSlots[i].isValid()) {
            return false;
        }
        m_gbufferImages[i] = image.image;
        m_gbufferHandles[i] = m_desc.bindless->shaderHandle(m_gbufferSlots[i]);
    }
    ++m_stats.gbufferBinds;
    return true;
}

bool RtEffects::beginFrame(u64 frameSerial, const RtEffectsFrameDesc& desc) {
    if (!m_initialized || desc.gbuffer == nullptr) {
        return false;
    }
    m_frameSerial = frameSerial;
    m_recordCount = 0;
    m_stats.shadowPasses = 0;
    m_stats.reflectionPasses = 0;
    m_stats.shadowRays = 0;
    m_stats.reflectionRays = 0;
    const u32 w = desc.gbuffer->width();
    const u32 h = desc.gbuffer->height();
    if (w == 0u || h == 0u) {
        return false;
    }
    if ((w != m_width || h != m_height || m_output.handle == nullptr) && !createOutput(w, h)) {
        return false;
    }
    if (!bindGBuffer(*desc.gbuffer) || !buildFrameConstants(desc, w, h, m_constants)) {
        return false;
    }
    const u64 base = m_output.deviceAddress;
    m_constants.view.visibility = base + m_layout.visibility;
    m_constants.hitDistance = base + m_layout.hitDistance;
    m_constants.reflection = base + m_layout.reflection;
    m_constants.gbufferNormal = m_gbufferHandles[0];
    m_constants.gbufferRoughMetal = m_gbufferHandles[1];
    m_constants.gbufferDepth = m_gbufferHandles[2];
    const u64 offset = (frameSerial % m_desc.framesInFlight) * kFrameStride;
    std::memcpy(static_cast<u8*>(m_frameRing.mapped) + offset, &m_constants, sizeof(m_constants));
    m_frameAddress = m_frameRing.deviceAddress + offset;
    return true;
}

RtEffectsGraphRefs RtEffects::importInto(rg::Graph& graph) {
    RtEffectsGraphRefs refs{};
    if (!m_initialized || m_output.handle == nullptr) {
        return refs;
    }
    refs.output = graph.importBuffer(rg::ImportedBuffer{m_output.handle, m_output.desc.size, m_outputQueue, &m_outputQueue,
                                                        "rt_effects.output"});
    return refs;
}

bool RtEffects::addShadows(rg::Graph& graph, const RtEffectsGraphRefs& refs, rg::BufferRef tlas,
                           const material_resolve::ResolveGraphRefs& gbuffer, const RtEffectsDump& dump) {
    if (!m_initialized || !refs.output.valid() || !tlas.valid() || m_constants.view.count == 0u || m_constants.tlas == 0u ||
        m_recordCount >= kMaxPasses) {
        return false;
    }
    for (const u32 attachment : kGBufferAttachments) {
        if (!gbuffer.gbuffer[attachment].valid()) {
            return false;
        }
    }
    PassRecord& r = m_records[m_recordCount++];
    r = PassRecord{};
    r.self = this;
    r.kernel = kShadows;
    r.push.frame = m_frameAddress;
    r.push.dump = dump.buffer.valid() ? dump.address : 0u;
    rg::PassBuilder pass = graph.addPass("rt.shadows", &RtEffects::recordDispatch, &r);
    pass.use(tlas, rg::Access::AccelerationStructureRead, {}, rg::kStageCompute);
    for (const u32 attachment : kGBufferAttachments) {
        pass.use(gbuffer.gbuffer[attachment], rg::Access::SampledRead, {}, rg::kStageCompute);
    }
    const u64 pixels = static_cast<u64>(m_width) * m_height;
    pass.use(refs.output, rg::Access::StorageWrite, rg::BufferRange{m_layout.visibility, m_layout.reflection - m_layout.visibility},
             rg::kStageCompute);
    if (dump.buffer.valid()) {
        pass.use(dump.buffer, rg::Access::StorageWrite, rg::BufferRange{0, pixels * m_constants.view.count * sizeof(RtfxRayRecord)},
                 rg::kStageCompute);
    }
    u32 rays = 0;
    for (u32 c = 0; c < m_constants.view.count; ++c) {
        rays += m_constants.shadowLights[c].samples;
    }
    m_stats.shadowRays = static_cast<u32>(std::min<u64>(pixels * rays, 0xFFFFFFFFu));
    ++m_stats.shadowPasses;
    return true;
}

bool RtEffects::addReflections(rg::Graph& graph, const RtEffectsGraphRefs& refs, rg::BufferRef tlas,
                               const material_resolve::ResolveGraphRefs& gbuffer, const gpu_scene::GpuSceneGraphRefs& scene,
                               const RtEffectsDump& dump) {
    if (!m_initialized || !refs.output.valid() || !tlas.valid() || m_constants.reflectionSamples == 0u || m_constants.tlas == 0u ||
        m_recordCount >= kMaxPasses) {
        return false;
    }
    for (const u32 attachment : kGBufferAttachments) {
        if (!gbuffer.gbuffer[attachment].valid()) {
            return false;
        }
    }
    PassRecord& r = m_records[m_recordCount++];
    r = PassRecord{};
    r.self = this;
    r.kernel = kReflections;
    r.push.frame = m_frameAddress;
    r.push.dump = dump.buffer.valid() ? dump.address : 0u;
    rg::PassBuilder pass = graph.addPass("rt.reflections", &RtEffects::recordDispatch, &r);
    pass.use(tlas, rg::Access::AccelerationStructureRead, {}, rg::kStageCompute);
    gpu_scene::GpuScene::useAll(pass, scene, rg::Access::StorageRead, rg::kStageCompute);
    for (const u32 attachment : kGBufferAttachments) {
        pass.use(gbuffer.gbuffer[attachment], rg::Access::SampledRead, {}, rg::kStageCompute);
    }
    const u64 pixels = static_cast<u64>(m_width) * m_height;
    pass.use(refs.output, rg::Access::StorageWrite, rg::BufferRange{m_layout.reflection, pixels * sizeof(RtfxReflectionTexel)},
             rg::kStageCompute);
    if (dump.buffer.valid()) {
        pass.use(dump.buffer, rg::Access::StorageWrite, rg::BufferRange{0, pixels * sizeof(RtfxRayRecord)}, rg::kStageCompute);
    }
    m_stats.reflectionRays = static_cast<u32>(std::min<u64>(pixels * m_constants.reflectionSamples, 0xFFFFFFFFu));
    ++m_stats.reflectionPasses;
    return true;
}

void RtEffects::addSamplingUse(rg::Graph& graph, const RtEffectsGraphRefs& refs, u8 stages) {
    if (!m_initialized || !refs.output.valid()) {
        return;
    }
    const u64 pixels = static_cast<u64>(m_width) * m_height;
    rg::PassBuilder pass = graph.addPass("rt.shadow_use", nullptr, nullptr);
    pass.neverCull();
    pass.use(refs.output, rg::Access::StorageRead, rg::BufferRange{m_layout.visibility, pixels * kRtfxMaxShadowLights * 4u}, stages);
}

void RtEffects::recordDispatch(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const PassRecord& r = *static_cast<const PassRecord*>(user);
    const RtEffects& self = *r.self;
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(self.m_pipelines[r.kernel]));
    self.m_desc.bindless->bind(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, self.m_layoutHandle, 0);
    vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(self.m_layoutHandle), VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(RtfxPush), &r.push);
    vkCmdDispatch(cmd, groups(self.m_width, kRtfxTile), groups(self.m_height, kRtfxTile), 1u);
#else
    (void)context;
    (void)user;
#endif
}

} // namespace fuse::renderer::rt_effects
